"""Modular arithmetic in cycles, clocks, packaging, and powers."""
from algebra_lessons import authored
from number_theory_lessons import source
from card_lessons import make_lessons

def e(w,q):return source('modular-arithmetic',w,q)
SPECS=[
authored('modular-repeating-colors','Locate an item in a repeating color pattern',
 'Beads repeat Blue, Gold, White, Purple.\nThe first bead is Blue.\nWhat color is bead 347?','White',
 'Beads repeat blue, gold, white, purple. The first bead is blue. What color is bead three hundred forty-seven?',[
 ('LABEL ONE CYCLE','There are four positions in each repeating block','1: Blue; 2: Gold; 3: White; 4: Purple',
 'Label the positions in one block. Blue is first, gold second, white third, and purple fourth.'),
 ('REMOVE COMPLETE BLOCKS','Each block contains four beads','347 = 4 × 86 + 3',
 'Divide three hundred forty-seven by four. There are eighty-six complete blocks, with three beads into the next block.'),
 ('MATCH THE POSITION','Remainder three points to the third color','347 mod 4 = 3\nPosition 3 is White.',
 'Remainder three means the third position in the block. The color is white.'),
 ('HANDLE THE ZERO CASE','With positions starting at one, zero means the last item','Remainder 0 → position 4, Purple\nRemainder 3 → position 3, White',
 'For patterns numbered from one, remainder zero means the last position. Always connect the remainder to the original position labels.')],e('1HWa',1),expression='347%4',value='3'),
authored('modular-round-robin-sharing','Count a first player’s share after circular dealing',
 'Deal 67 tokens one at a time\nto 6 players in a fixed circle.\nHow many does the first player receive?','12',
 'Deal sixty-seven tokens one at a time to six players in a fixed circle. How many tokens does the first player receive?',[
 ('COUNT COMPLETE ROUNDS','Each full round gives every player one token','67 = 6 × 11 + 1',
 'A complete round uses six tokens. Sixty-seven tokens make eleven full rounds with one token left.'),
 ('GIVE EVERYONE THE BASE SHARE','Eleven full rounds give eleven tokens each','Each player receives 11 tokens from full rounds.',
 'Each player receives eleven tokens from the eleven complete rounds.'),
 ('DISTRIBUTE THE LEFTOVERS','The next round starts again with player one','One token remains.\nPlayer 1 receives that extra token.',
 'The leftover token starts the next round, so it goes to the first player.'),
 ('ADD THE FIRST PLAYER’S TOTAL','A positive remainder gives player one an extra token','11 + 1 = 12\nIf the remainder were zero, everyone would get 11.',
 'The first player receives eleven plus one, or twelve tokens. A zero remainder would mean no extra token.')],e('1HWa',4),expression='11+1',value='12',equalities=[('6*11+1','67')]),
authored('modular-clock-elapsed-hours','Find clock time after an elapsed number of hours',
 'A clock shows 19:00.\nWhat will it show 58 hours later\nin 24-hour and 12-hour formats?','05:00; 5:00 AM',
 'A clock shows nineteen hundred, or seven P M. What will it show fifty-eight hours later in twenty-four-hour and twelve-hour formats?',[
 ('ADD THE ELAPSED HOURS','The starting hour is an offset','19 + 58 = 77 hours',
 'Add the fifty-eight elapsed hours to the starting hour, nineteen. The total is seventy-seven.'),
 ('REMOVE COMPLETE DAYS','A full day has twenty-four hours','77 = 24 × 3 + 5\n24-hour time: 05:00',
 'Remove complete twenty-four-hour days. Seventy-seven leaves remainder five, so the twenty-four-hour display is zero five hundred.'),
 ('READ THE TWELVE-HOUR FACE','Morning hours below twelve are AM','05:00 is 5:00 AM.\nOn a 12-hour face, 77 mod 12 = 5.',
 'Five hundred is five A M. Reducing the total modulo twelve also gives the face value five.'),
 ('CHECK THE WRAP','A remainder of zero uses different clock labels','24-hour remainder 0 → 00:00\n12-hour remainder 0 → 12:00',
 'Remember the zero case. A twenty-four-hour display uses zero hundred, while a twelve-hour face labels zero as twelve.')],e('1HWb',3),equalities=[('(19+58)%24','5'),('(19+58)%12','5')]),
authored('modular-weekday-offset','Find weekdays from elapsed days and numbered events',
 'A club first meets on Wednesday, then every 6 days.\nWhat weekday is its 9th meeting?\nWhat weekday is 100 days after that first meeting?','Tuesday; Friday',
 'A club first meets on Wednesday and then every six days. Find the weekday of its ninth meeting, and the weekday one hundred days after the first meeting.',[
 ('COUNT THE GAPS','The first meeting is already counted','9th meeting → 9 − 1 = 8 gaps\nElapsed days = 8 × 6 = 48',
 'The ninth meeting is eight gaps after the first. At six days per gap, forty-eight days have elapsed.'),
 ('REDUCE BY THE WEEK LENGTH','Whole weeks return to the same weekday','48 mod 7 = 6\nSix days after Wednesday is Tuesday.',
 'Forty-eight modulo seven is six. Move six days forward from Wednesday to reach Tuesday.'),
 ('USE DIRECT ELAPSED TIME','One hundred days already states the number of days','100 mod 7 = 2\nTwo days after Wednesday is Friday.',
 'For one hundred elapsed days, no event adjustment is needed. The remainder is two, so the weekday is Friday.'),
 ('KEEP THE TWO COUNTS DISTINCT','Numbered events have one fewer gap than events','Event k every d days: elapsed = (k − 1)d\nThen move elapsed mod 7 days from the start.',
 'For the kth event, use k minus one intervals. Then reduce the elapsed days modulo seven and count forward from the starting weekday.')],e(4,4),equalities=[('((9-1)*6)%7','6'),('100%7','2')]),
authored('modular-circular-movement','Track repeated jumps around a numbered circle',
 'A token starts at position 4 on a ring labelled 0–9.\nIt moves backward 3 positions, 17 times.\nWhere does it finish?','3',
 'A token starts at position four on a ring labelled zero through nine. It moves backward three positions, seventeen times. Where does it finish?',[
 ('FIND THE SIGNED MOVEMENT','Backward moves are negative','Total movement = 17 × (−3) = −51',
 'Backward moves have negative sign. Seventeen jumps of negative three give total movement negative fifty-one.'),
 ('INCLUDE THE STARTING POSITION','Add movement to the starting label','4 + (−51) = −47',
 'Add the signed movement to the starting position. Four minus fifty-one equals negative forty-seven.'),
 ('WRAP AROUND THE RING','Ten positions make one full circuit','−47 + 5 × 10 = 3\nFinish at position 3.',
 'Add five complete circuits of ten to reach three. The token finishes at position three.'),
 ('ADAPT TO THE LABELS','The direction and label convention both matter','Forward: use + jumps. Backward: use − jumps.\nFor labels 1–10, remainder 0 is label 10.',
 'Use a positive sign for forward motion. If labels run from one through ten instead, interpret remainder zero as label ten.')],e('1HWb',4),expression='(4-17*3)%10',value='3'),
authored('modular-numbered-clock-events','Find clock time at a numbered repeating event',
 'A bell first rings at 4:00, then every 7 hours.\nWhat does a 12-hour clock show\nat the 8th ringing, counting the first?','5:00',
 'A bell first rings at four o’clock and then every seven hours. What does a twelve-hour clock show at the eighth ringing, counting the first?',[
 ('COUNT THE INTERVALS','The first ringing happens before any waiting','8 ringings → 7 intervals',
 'Counting the first ringing, eight ringings contain seven waiting intervals.'),
 ('CALCULATE ELAPSED HOURS','Multiply the gaps by seven hours each','7 × 7 = 49 hours',
 'Seven intervals of seven hours each give forty-nine elapsed hours.'),
 ('ADD THE STARTING HOUR','Clock position depends on the starting time','4 + 49 = 53\n53 = 12 × 4 + 5',
 'Add the starting hour, four. Fifty-three is four twelves plus five.'),
 ('READ THE CLOCK FACE','Use twelve when the remainder is zero','53 mod 12 = 5 → 5:00\nGeneral rule: start + (event number − 1) × interval',
 'The remainder is five, so the clock shows five o’clock. Add one fewer interval than the event number, then reduce modulo twelve.')],e(4,3),expression='(4+(8-1)*7)%12',value='5'),
authored('modular-traffic-light-phases','Identify the phase of a repeating traffic light',
 'A light repeats Green 35 s, Yellow 6 s, Red 24 s.\nIt begins Green now.\nWhat color is it after 8 minutes 17 seconds?','Red',
 'A light repeats green for thirty-five seconds, yellow for six, and red for twenty-four. It begins green now. What color is it after eight minutes seventeen seconds?',[
 ('MEASURE ONE FULL CYCLE','Add the lengths of all phases','35 + 6 + 24 = 65 seconds',
 'Add all three phase lengths. One complete cycle lasts sixty-five seconds.'),
 ('CONVERT TO ONE UNIT','Use seconds for both elapsed time and the cycle','8 min 17 s = 8 × 60 + 17 = 497 seconds',
 'Convert the elapsed time to seconds. Eight minutes seventeen seconds is four hundred ninety-seven seconds.'),
 ('FIND THE POSITION IN THE CYCLE','Remove complete cycles','497 = 65 × 7 + 42\nPosition: 42 seconds into the cycle',
 'Remove seven complete cycles. The remainder is forty-two seconds into the current cycle.'),
 ('COMPARE WITH THE PHASE BOUNDARIES','Use the start and end of each color interval','Green: 0 ≤ t < 35; Yellow: 35 ≤ t < 41\nRed: 41 ≤ t < 65, so t = 42 is Red.',
 'Green ends at thirty-five seconds and yellow at forty-one. Forty-two lies in the red interval, so the light is red.')],e('4HWa',5),expression='(8*60+17)%(35+6+24)',value='42'),
authored('modular-slow-clock','Convert actual elapsed time to a slow clock’s reading',
 'A clock records only 23 hours per actual day.\nSet it correctly at midnight.\nWhat does its 12-hour face show 4 days later?','8:00',
 'A clock records only twenty-three hours per actual day. Set it correctly at midnight. What does its twelve-hour face show four days later?',[
 ('COUNT THE ACTUAL TIME','Four days contain ninety-six actual hours','4 × 24 = 96 actual hours',
 'Four actual days contain ninety-six hours.'),
 ('APPLY THE CLOCK’S RATE','Use twenty-three recorded hours for each actual day','4 × 23 = 92 recorded hours',
 'The slow clock records only twenty-three hours per day. Across four days, it records ninety-two hours.'),
 ('REDUCE THE RECORDED TIME','A twelve-hour face repeats every twelve hours','92 = 12 × 7 + 8\n92 mod 12 = 8',
 'Reduce the recorded time modulo twelve. Ninety-two hours leave remainder eight.'),
 ('CHECK USING THE LOST TIME','Four hours lost from midnight shows eight','Actual 96 h − lost 4 h = recorded 92 h\nThe clock face shows 8:00.',
 'As a check, the clock loses four hours in four days. Four hours before midnight is eight o’clock on its face.')],e(4,9),expression='(4*23)%12',value='8'),
authored('modular-caesar-letter-shift','Wrap an alphabet shift using modulo twenty-six',
 'A Caesar cipher shifts each letter forward by 7.\nUsing A=1, …, Z=26,\nwhat does V become?','C',
 'A Caesar cipher shifts each letter forward by seven. Using A equals one through Z equals twenty-six, what does V become?',[
 ('CONVERT THE LETTER','Keep one consistent alphabet numbering system','V is letter 22.',
 'With A numbered one, V is letter twenty-two.'),
 ('APPLY THE SHIFT','Forward means add seven','22 + 7 = 29',
 'Add the forward shift of seven. The result is twenty-nine, beyond the end of the alphabet.'),
 ('WRAP AT TWENTY-SIX','Remove a complete alphabet','29 − 26 = 3\nLetter 3 is C.',
 'Subtract one complete alphabet of twenty-six letters. The remainder is three, which corresponds to C.'),
 ('HANDLE ALPHABET ENDPOINTS','In this numbering, remainder zero stands for Z','With A=1, …, Z=26: remainder 0 → Z\nV shifted forward 7 becomes C.',
 'In this one-based numbering, remainder zero means Z. Here the remainder is three, so V becomes C.')],e(4,10),expression='(22+7)%26',value='3'),
authored('modular-power-cycles','Use short residue cycles to evaluate large powers',
 'Find 3⁴⁷ mod 10 and 6¹²⁰ mod 5.','7 and 1',
 'Find the remainders of three to the forty-seventh power modulo ten, and six to the one hundred twentieth power modulo five.',[
 ('BUILD A SHORT POWER CYCLE','Multiply by three and keep only the units digit','3¹, 3², 3³, 3⁴ → 3, 9, 7, 1\nThe next residue is 3 again: cycle length 4.',
 'The units digits of powers of three are three, nine, seven, one, and then repeat. The cycle has length four.'),
 ('LOCATE THE EXPONENT','The first power is position one in the cycle','47 = 4 × 11 + 3\nPosition 3 gives 3⁴⁷ mod 10 = 7.',
 'Forty-seven leaves remainder three when divided by four. Use the third position in the cycle, giving seven.'),
 ('LOOK FOR A ONE-STEP CYCLE','A base congruent to one stays one when raised to a power','6 ≡ 1 (mod 5)\n6¹²⁰ ≡ 1¹²⁰ ≡ 1 (mod 5)',
 'For the second calculation, six is congruent to one modulo five. Every positive power therefore leaves remainder one.'),
 ('KEEP EXPONENT AND BASE ROLES CLEAR','Reduce the exponent by the cycle length','Cycle length 4: exponent remainder 0 → position 4\nFinal remainders: 7 and 1',
 'Reduce an exponent by the length of its residue cycle. In a cycle numbered from one, exponent remainder zero selects the last position.')],e('4HWb',4),equalities=[('3**47%10','7'),('6**120%5','1')]),
authored('modular-packaging-leftovers','Find leftovers after production and packing',
 'A workshop makes 83 badges per hour for 7 hours.\nBadges go into full boxes of 9.\nHow many badges remain unpacked?','5',
 'A workshop makes eighty-three badges per hour for seven hours. Badges go into full boxes of nine. How many badges remain unpacked?',[
 ('FIND THE TOTAL','Multiply the hourly rate by the number of hours','83 × 7 = 581 badges',
 'First find the total production. Eighty-three times seven is five hundred eighty-one badges.'),
 ('COUNT FULL BOXES','Each complete box uses nine badges','9 × 64 = 576\n9 × 65 = 585, which is too many.',
 'Sixty-four boxes use five hundred seventy-six badges. Sixty-five boxes would require too many.'),
 ('SUBTRACT THE PACKED BADGES','The remainder is the unpacked amount','581 − 576 = 5\n581 = 9 × 64 + 5',
 'Subtract the packed badges from the total. Five badges remain unpacked.'),
 ('CHECK THE REMAINDER','Enough for another box would not be a final remainder','0 ≤ 5 < 9\n64 full boxes and 5 badges left over',
 'The leftover amount is less than nine, so it cannot fill another box. There are sixty-four full boxes and five badges left over.')],e('4HWb',3),expression='83*7%9',value='5'),
authored('modular-multiple-plus-offset','Ignore a known multiple when finding a remainder',
 'M is an integer multiple of 8.\nWhat remainder does M + 21 leave\nwhen divided by 8?','5',
 'M is an integer multiple of eight. What remainder does M plus twenty-one leave when divided by eight?',[
 ('WRITE THE GIVEN MULTIPLE','Use an integer k to represent any multiple','M = 8k, so M mod 8 = 0.',
 'Write M as eight k for some integer k. Its remainder modulo eight is zero.'),
 ('SPLIT THE OFFSET','Separate twenty-one into a multiple and a remainder','21 = 8 × 2 + 5',
 'Twenty-one is two eights plus five.'),
 ('COMBINE THE MULTIPLES','The unknown multiple changes the quotient only','M + 21 = 8k + 16 + 5\n= 8(k + 2) + 5',
 'Combine eight k and sixteen into eight times k plus two. The leftover part is still five.'),
 ('READ THE REMAINDER','The answer does not depend on the original multiple','0 ≤ 5 < 8\nThe remainder is 5 for every allowed M.',
 'Five lies in the allowed range from zero through seven. The remainder is five, whatever integer multiple M represents.')],e('1HWb',5),identities=[('8*k+21','8*(k+2)+5')]),
]
def lessons(doc):return make_lessons(SPECS,doc)
